# Pulumi TypeScript ComponentResource: Application Stack

Here's an idiomatic Pulumi implementation wrapping S3, RDS, and IAM into a reusable ComponentResource with dev/prod support:

## Directory Structure

```
.
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── Pulumi.yaml
├── index.ts
└── components/
    └── applicationStack.ts
```

## Component Definition

**`components/applicationStack.ts`**

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ApplicationStackArgs {
  bucketName: string;
  dbInstanceIdentifier: string;
  environment: "dev" | "prod";
  vpcId: string;
  dbSubnetGroupName: string;
  allocatedStorage: number;
  instanceClass: string;
}

export class ApplicationStackComponent extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.Bucket;
  public readonly rdsInstance: aws.rds.Instance;
  public readonly iamRole: aws.iam.Role;
  public readonly bucketArn: pulumi.Output<string>;
  public readonly rdsEndpoint: pulumi.Output<string>;
  public readonly roleArn: pulumi.Output<string>;

  constructor(
    name: string,
    args: ApplicationStackArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:infrastructure:ApplicationStackComponent", name, {}, opts);

    const componentOpts = { parent: this };

    // ============================================
    // 1. S3 Bucket: versioning + encryption + secure
    // ============================================
    this.bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: args.bucketName,
        forceDestroy: args.environment === "dev", // clean destroy in dev only
      },
      componentOpts
    );

    new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: this.bucket.id,
        versioningConfiguration: { status: "Enabled" },
      },
      componentOpts
    );

    new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-sse`,
      {
        bucket: this.bucket.id,
        rules: [
          {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256", // or KMS key for prod
            },
          },
        ],
      },
      componentOpts
    );

    new aws.s3.BucketPublicAccessBlock(
      `${name}-pab`,
      {
        bucket: this.bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      componentOpts
    );

    // ============================================
    // 2. RDS PostgreSQL: deletion protection + backups
    // ============================================
    const dbPassword = getDbPassword();

    this.rdsInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: args.dbInstanceIdentifier,
        engine: "postgres",
        engineVersion: "15.5",
        instanceClass: args.instanceClass,
        allocatedStorage: args.allocatedStorage,
        dbName: "appdb",
        username: "dbadmin",
        password: dbPassword,
        dbSubnetGroupName: args.dbSubnetGroupName,
        // Security: no public access
        publiclyAccessible: false,
        // Deletion protection (always on)
        deletionProtection: true,
        // Backup retention
        backupRetentionPeriod: args.environment === "prod" ? 30 : 7,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "sun:04:00-sun:05:00",
        // Encryption
        storageEncrypted: true,
        // High availability for prod
        multiAz: args.environment === "prod",
        // Snapshots
        copyTagsToSnapshot: true,
        skipFinalSnapshot: args.environment === "dev",
        finalSnapshotIdentifier:
          args.environment === "prod"
            ? pulumi.interpolate`${args.dbInstanceIdentifier}-final-${Date.now()}`
            : undefined,
        // Updates
        autoMinorVersionUpgrade: false,
        applyImmediately: args.environment === "dev",
      },
      componentOpts
    );

    // ============================================
    // 3. IAM Role: least-privilege service account
    // ============================================
    const trustPolicy = {
      Version: "2012-10-17",
      Statement: [
        {
          Action: "sts:AssumeRole",
          Effect: "Allow",
          Principal: {
            Service: "ec2.amazonaws.com", // EKS node instances
          },
        },
      ],
    };

    this.iamRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        name: `${name}-service-${args.environment}`,
        assumeRolePolicy: JSON.stringify(trustPolicy),
        tags: {
          Environment: args.environment,
        },
      },
      componentOpts
    );

    // Inline policy with environment-specific permissions
    new aws.iam.RolePolicy(
      `${name}-policy`,
      {
        role: this.iamRole.id,
        policy: pulumi
          .all([this.bucket.arn, this.rdsInstance.arn])
          .apply(([bucketArn, rdsArn]) =>
            JSON.stringify({
              Version: "2012-10-17",
              Statement: [
                {
                  Sid: "S3AssetAccess",
                  Effect: "Allow",
                  Action:
                    args.environment === "prod"
                      ? ["s3:GetObject", "s3:ListBucket"] // read-only in prod
                      : [
                          "s3:GetObject",
                          "s3:PutObject",
                          "s3:DeleteObject",
                          "s3:ListBucket",
                        ], // read-write in dev
                  Resource: [bucketArn, `${bucketArn}/*`],
                },
                {
                  Sid: "RDSDatabaseConnect",
                  Effect: "Allow",
                  Action: ["rds-db:connect"],
                  Resource: rdsArn,
                },
                {
                  Sid: "SecretsManagerRead",
                  Effect: "Allow",
                  Action: [
                    "secretsmanager:GetSecretValue",
                    "secretsmanager:DescribeSecret",
                  ],
                  Resource: pulumi.interpolate`arn:aws:secretsmanager:*:*:secret:${args.environment}/db-*`,
                },
              ],
            })
          ),
      },
      componentOpts
    );

    // Capture outputs
    this.bucketArn = this.bucket.arn;
    this.rdsEndpoint = this.rdsInstance.endpoint;
    this.roleArn = this.iamRole.arn;

    this.registerOutputs({
      bucketArn: this.bucketArn,
      rdsEndpoint: this.rdsEndpoint,
      roleArn: this.roleArn,
    });
  }
}

function getDbPassword(): pulumi.Output<string> {
  const config = new pulumi.Config();
  return config.requireSecret("dbPassword");
}
```

## Stack Configuration

**`Pulumi.dev.yaml`**

```yaml
config:
  aws:region: us-east-1
  bucketName: my-app-assets-dev
  dbInstanceIdentifier: my-app-db-dev
  vpcId: vpc-dev123
  dbSubnetGroupName: default
  allocatedStorage: 20
  instanceClass: db.t3.micro
  dbPassword:
    secure: AAABAxxxxx...
```

**`Pulumi.prod.yaml`**

```yaml
config:
  aws:region: us-east-1
  bucketName: my-app-assets-prod
  dbInstanceIdentifier: my-app-db-prod
  vpcId: vpc-prod456
  dbSubnetGroupName: prod-subnet-group
  allocatedStorage: 100
  instanceClass: db.t3.medium
  dbPassword:
    secure: AAABAyyyyy...
```

## Main Stack File

**`index.ts`**

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ApplicationStackComponent } from "./components/applicationStack";

const config = new pulumi.Config();
const environment = pulumi.getStack();

// Load environment-specific configuration
const bucketName = config.require("bucketName");
const dbInstanceIdentifier = config.require("dbInstanceIdentifier");
const vpcId = config.require("vpcId");
const dbSubnetGroupName = config.require("dbSubnetGroupName");
const allocatedStorage = config.requireNumber("allocatedStorage");
const instanceClass = config.require("instanceClass");

// Instantiate the component
const appStack = new ApplicationStackComponent("app", {
  bucketName,
  dbInstanceIdentifier,
  environment: environment as "dev" | "prod",
  vpcId,
  dbSubnetGroupName,
  allocatedStorage,
  instanceClass,
});

// Export stack outputs for consumption
export const bucketArn = appStack.bucketArn;
export const bucketName_ = appStack.bucket.id;
export const rdsEndpoint = appStack.rdsEndpoint;
export const rdsArn = appStack.rdsInstance.arn;
export const iamRoleArn = appStack.roleArn;
export const iamRoleName = appStack.iamRole.name;
```

## Usage

```bash
# Set secrets (one-time per stack)
pulumi config set --secret dbPassword "your-db-password" --stack dev
pulumi config set --secret dbPassword "your-prod-db-password" --stack prod

# Deploy to dev
pulumi up --stack dev

# Deploy to prod (isolated state)
pulumi up --stack prod

# Outputs per environment
pulumi stack output bucketArn --stack dev
pulumi stack output bucketArn --stack prod  # different ARN
```

## Compliance with Acceptance Criteria

| Criterion | Implementation |
|-----------|-----------------|
| **Bucket versioning** | `BucketVersioningV2` with `status: "Enabled"` |
| **Encryption** | `BucketServerSideEncryptionConfigurationV2` with AES-256 |
| **No public access** | `BucketPublicAccessBlock` with all restrictions enabled |
| **RDS deletion protection** | `deletionProtection: true` (always on) |
| **Backup retention** | 30 days prod / 7 days dev |
| **RDS not public** | `publiclyAccessible: false` |
| **IAM least privilege** | prod: read-only S3; dev: read-write; RDS `rds-db:connect` only |
| **No wildcard actions in prod** | explicit action list in prod policy; `s3:*` only in dev |
| **Environment isolation** | separate stacks (dev.yaml / prod.yaml); independent state files |
| **Secret management** | `config.requireSecret("dbPassword")` — never in plaintext; encrypted at rest via Pulumi secrets backend |
